public class StringMethodsRef {
    public static void main(String[] args) {
        String s = "  Hello, Java World!  ";

        // Length and access
        System.out.println(s.length());        // 22 — total characters including spaces
        System.out.println(s.charAt(2));       // H — index 0-based, includes leading spaces
        System.out.println(s.isEmpty());       // false
        System.out.println("".isEmpty());      // true
        System.out.println("  ".isBlank());    // true — Java 11+, whitespace-only counts

        // Substring — end is EXCLUSIVE
        System.out.println(s.substring(2, 7)); // Hello
        System.out.println(s.substring(9));    // Java World!   (from index to end)

        // Search
        System.out.println(s.indexOf("Java"));   // 9 — first occurrence, -1 if not found
        System.out.println(s.contains("World")); // true
        System.out.println(s.startsWith("  H")); // true
        System.out.println(s.endsWith("!  "));   // true

        // Transform — always returns new String, never modifies s
        System.out.println(s.toUpperCase());  // uppercase version
        System.out.println(s.toLowerCase());  // lowercase version
        System.out.println(s.trim());         // removes leading/trailing ASCII whitespace
        System.out.println(s.strip());        // Java 11 — same but Unicode-aware

        // Replace
        System.out.println(s.replace("Java", "Python")); // replaces all occurrences
        System.out.println(s.trim().replace(", ", " ")); // chains are fine

        // Split
        String csv = "a,b,c,d";
        String[] parts = csv.split(",");
        System.out.println(parts.length); // 4
        System.out.println(parts[0]);     // a

        // Type conversion
        String num = String.valueOf(42);      // '42' — int to String
        int n = Integer.parseInt("99");       // 99 — String to int
        double d = Double.parseDouble("3.14"); // 3.14
    }
}
