public class FormatDemo {
    public static void main(String[] args) {

        String name = "Alice";
        int age = 28;
        double score = 95.678;

        // Basic usage — %s for string, %d for int, %f for double
        String msg = String.format("Name: %s, Age: %d, Score: %f", name, age, score);
        System.out.println(msg); // Name: Alice, Age: 28, Score: 95.678000

        // Control decimal places with %.Nf
        String scoreMsg = String.format("Score: %.2f", score);
        System.out.println(scoreMsg); // Score: 95.68

        // Padding and alignment
        System.out.printf("%-15s %5d%n", "Alice", 95);  // Alice              95
        System.out.printf("%-15s %5d%n", "Bob", 72);    // Bob                72

        // printf() = String.format() + print — no assignment needed
        System.out.printf("Hello, %s! You scored %d points.%n", name, (int) score);
        // Hello, Alice! You scored 95 points.

        // Using formatted() — instance method in Java 15+
        String result = "User %s has %d tokens".formatted(name, 10);
        System.out.println(result); // User Alice has 10 tokens
    }
}
