public class SubstringDemo {
    public static void main(String[] args) {
        String s = "hello";
        //           01234   — index positions

        System.out.println(s.substring(1, 3)); // el  — indices 1 and 2 only
        System.out.println(s.substring(0, 5)); // hello — all 5 chars
        System.out.println(s.substring(2));    // llo — from index 2 to end

        // Length formula: end - start = result length
        System.out.println(s.substring(1, 4).length()); // 3 (= 4 - 1)

        // Common mistake
        System.out.println(s.substring(0, 4)); // hell — NOT hello!
        // To get 'hello': substring(0, 5) or substring(0, s.length())

        // Practical use: extract domain from email
        String email = "alice@example.com";
        int at = email.indexOf('@');               // 5
        String domain = email.substring(at + 1);   // example.com
        System.out.println(domain);

        // Extract filename without extension
        String file = "report.pdf";
        int dot = file.lastIndexOf('.');
        String name = file.substring(0, dot);      // report
        System.out.println(name);
    }
}
