public class SplitDemo {
    public static void main(String[] args) {

        // Basic split — comma, no regex issue
        String csv = "Alice,Bob,Carol";
        String[] names = csv.split(",");
        System.out.println(names.length); // 3
        System.out.println(names[0]);     // Alice

        // PITFALL 1: dot is a regex metacharacter — matches ANY character
        String filename = "report.2024.pdf";
        String[] buggy = filename.split(".");   // WRONG — splits on every char
        System.out.println(buggy.length);       // 0 — all matches, all empty!

        String[] correct = filename.split("\\."); // escape the dot
        System.out.println(correct.length);       // 3
        System.out.println(correct[0]);           // report

        // PITFALL 2: pipe | is regex OR — must escape it too
        String data = "a|b|c";
        // data.split("|")  — WRONG: | means 'or nothing' in regex, splits every char
        String[] fixed = data.split("\\|");
        System.out.println(fixed.length); // 3

        // PITFALL 3: trailing empty strings removed by default
        String csv2 = "a,,b,,";
        String[] parts = csv2.split(",");
        System.out.println(parts.length); // 3 — trailing empties dropped

        String[] all = csv2.split(",", -1); // -1 keeps all including trailing empty strings
        System.out.println(all.length);     // 5

        // Limit argument — cap the number of pieces
        String line = "one:two:three:four";
        String[] limited = line.split(":", 2);
        System.out.println(limited[0]); // one
        System.out.println(limited[1]); // two:three:four — rest unsplit
    }
}
