public class ReplaceDemo {
    public static void main(String[] args) {
        String s = "a.b.c.d";

        // replace() — treats '.' as literal dot
        System.out.println(s.replace(".", "-"));     // a-b-c-d

        // replaceAll() — '.' is regex metachar = any character
        System.out.println(s.replaceAll(".", "-"));  // ------- (replaces every char!)

        // replaceAll() correct use — escape the dot
        System.out.println(s.replaceAll("\\.", "-")); // a-b-c-d

        // replaceAll() genuine use case — collapse multiple spaces
        String messy = "Hello    World   !";
        System.out.println(messy.replaceAll("\\s+", " ")); // Hello World !

        // replaceAll() — remove all digits
        String code = "abc123def456";
        System.out.println(code.replaceAll("\\d+", ""));   // abcdef

        // replaceFirst() — only the first match
        System.out.println("aabbcc".replaceFirst("b", "X")); // aaXbcc
    }
}
